<?php
namespace Tests\Feature;
use App\Services\Assessment\AssessmentRegistrationService;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;use Tests\TestCase;
class AssessmentRegistrationTest extends TestCase{private array$id;protected function setUp():void{parent::setUp();Schema::dropIfExists('assessment_registrations');Schema::dropIfExists('learners');Schema::create('learners',function(Blueprint$t){$t->uuid('id')->primary();$t->uuid('school_id');$t->boolean('active');$t->boolean('is_deleted');});Schema::create('assessment_registrations',function(Blueprint$t){$t->uuid('id')->primary();$t->uuid('school_id');$t->uuid('learner_id');$t->string('assessment_type');$t->integer('assessment_year');$t->string('candidate_number');$t->string('registration_number');$t->string('status');$t->uuid('created_by')->nullable();$t->boolean('is_deleted');$t->timestamp('created_at')->nullable();$t->timestamp('deleted_at')->nullable();$t->uuid('deleted_by')->nullable();});$this->id=['school'=>(string)Str::uuid(),'learner'=>(string)Str::uuid()];DB::table('learners')->insert(['id'=>$this->id['learner'],'school_id'=>$this->id['school'],'active'=>true,'is_deleted'=>false]);}
public function test_it_registers_an_active_tenant_learner():void{$x=app(AssessmentRegistrationService::class)->create($this->data(),$this->id['school'],null);$this->assertSame('pending',$x->status);$this->assertSame($this->id['school'],$x->school_id);}
public function test_it_rejects_duplicate_learner_registration():void{$s=app(AssessmentRegistrationService::class);$s->create($this->data(),$this->id['school'],null);$this->expectException(ValidationException::class);$s->create([...$this->data(),'candidate_number'=>'C2','registration_number'=>'R2'],$this->id['school'],null);}
public function test_it_rejects_cross_school_learners():void{$this->expectException(ValidationException::class);app(AssessmentRegistrationService::class)->create($this->data(),(string)Str::uuid(),null);}
private function data():array{return['learner_id'=>$this->id['learner'],'assessment_type'=>'KPSEA','assessment_year'=>2026,'candidate_number'=>'C-001','registration_number'=>'R-001'];}}
